+  it("forwards multiCursor to createEditor, enabling multi-selection", async () => {
+    let ready: EditorAPI | null = null;
+
+    const { container } = render(
+      <Editor
+        initialValue="hello world"
+        multiCursor
+        onReady={(editor) => {
+          ready = editor;
+        }}
+      />
